def add(n,cote,scans,lines,kind,words,statement,reconstruction,check,reason,sources):
    ident=f'SA14-{n}'
    loc=[f'{F57 if c==57 else F58}: {ll}' for c,ll in lines]
    ITEMS.append(dict(id=ident,sources=[f'MPL_{c}_{"271-315" if c==57 else "020-067"}#{i}' for c,i,v,r in sources],kind=kind,cote=cote,scans=scans,lines=loc,his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    for c,i,v,r in sources: ENTRIES.append(dict(entry_id=f'MPL_{c}_{"271-315" if c==57 else "020-067"}#{i}',item_id=ident,verdict=v,reason=r))
