add(286,58,[33,37],[(58,'511–547,674–709')],'conjecture','prof ≥2 ?','The author asks whether LG forces depth≥2 off Y; the nearby argument excludes associated points whose closure is disjoint from Y under the generating-family assumptions.','This closure-sensitive associated-point exclusion is weaker than depth≥2 at every point outside Y; the loci must not be conflated.','agrees','N16 does not promote the established necessary condition into the stronger conjecture.',[n58(16,'kept','Retain the distinction between associated-point exclusion and the next depth threshold.')])
