add(289,58,[38,39],[(58,'710–790')],'unproved claim','algèbres','Full faithfulness for vector bundles transports multiplication, unit, commutativity and associativity and therefore finite locally free algebra structures; étaleness can be arranged near Y.','The algebra identities must be checked by tensor powers. Effectivity algebraizes a cover only after possibly shrinking around Y.','agrees','N19 identifies the actual tensor-algebra mechanism.',[n58(19,'kept','Keep the proof of algebra-structure descent and its neighborhood qualification.')])
