add(291,58,[40,41],[(58,'791–883')],'unproved claim','H¹(Y,Λ^{-n})','Two stages are distinguished: compare Pic of algebraic neighborhoods to the formal completion using LG/Leff, then compare formal Pic to Pic(Y) using vanishing of H¹ and H² of the successive conormal powers for a Cartier divisor.','H¹ vanishing governs injectivity of isomorphism classes and H² vanishing their lifting; automorphisms require H⁰ control.','agrees','N21 correctly decomposes the argument.',[n58(21,'kept','Retain two separate comparisons and their distinct cohomological obstructions.')])
add(292,58,[41],[(58,'841–883')],'unproved claim','pleinement fidèle','The lemma’s categorical full-faithfulness/equivalence assertion from H¹/H² vanishing is false. For X=Spec k[[t]], Y=Spec k, all stated positive cohomology vanish, but the two automorphisms1 and1+t of O_X restrict to the same automorphism on Y.','The corresponding statement about Picard groups of isomorphism classes can hold; the categorical version needs an H⁰ condition on successive units.','agrees','N22 supplies a complete counterexample to faithfulness, not merely a dimension objection.',[n58(22,'kept','The automorphism calculation independently confirms failure even under the Cartier and vanishing hypotheses.')])
